"""Parse skill-scoped MCP imports into static binding metadata."""

from __future__ import annotations

import re
from typing import Callable, Mapping

from pydantic import BaseModel, ConfigDict, Field

from rasa.mantle.skills.catalog import SkillCatalog
from rasa.shared.utils.mcp.utils import (
    MAX_TOOL_NAME_LENGTH,
    PROVIDER_SAFE_TOOL_NAME_PATTERN,
)

_MCP_IMPORT_PATTERN = re.compile(
    r"^mcp/(?P<server_id>[A-Za-z0-9][A-Za-z0-9_.-]*):"
    r"(?P<tool_name>[A-Za-z0-9][A-Za-z0-9_.-]*)$"
)
# Server ids allow letters, digits, `_`, `.`, `-`, so ``com.acme.banking``
# parses the same as the YAML ``name`` value. Tool names are checked against the
# stricter provider rule instead, since they are offered to the LLM verbatim.


class MCPToolReference(BaseModel):
    """Parsed ``mcp/<server>:<tool>`` import reference."""

    model_config = ConfigDict(frozen=True)

    server_id: str = Field(min_length=1)
    tool_name: str = Field(min_length=1)


def try_parse_mcp_tool_import(tool_import_reference: str) -> MCPToolReference | None:
    """Parse an MCP import reference, returning ``None`` for local tool names."""
    if not tool_import_reference.startswith("mcp/"):
        return None
    match = _MCP_IMPORT_PATTERN.fullmatch(tool_import_reference)
    if match is None:
        raise ValueError(
            f"Invalid MCP tool import {tool_import_reference!r}; expected "
            "'mcp/<server-id>:<tool-name>'."
        )
    tool_name = match.group("tool_name")
    if not PROVIDER_SAFE_TOOL_NAME_PATTERN.fullmatch(tool_name):
        raise ValueError(
            f"Invalid MCP tool name {tool_name!r} in {tool_import_reference!r}; "
            "the tool name is sent to the LLM as a function name and may only "
            f"contain letters, digits, '_', and '-' "
            f"(at most {MAX_TOOL_NAME_LENGTH} characters)."
        )
    return MCPToolReference(
        server_id=match.group("server_id"),
        tool_name=tool_name,
    )


def get_bare_tool_name(tool_import_reference: str) -> str:
    """Return the callable name the skill registry and LLM see.

    ``mcp/<server-id>:<tool-name>`` yields ``tool-name``. Shared or local tool
    names are returned unchanged.
    """
    mcp_tool_ref = try_parse_mcp_tool_import(tool_import_reference)
    return mcp_tool_ref.tool_name if mcp_tool_ref is not None else tool_import_reference


def parse_mcp_imports(
    skill_catalog: SkillCatalog,
    skill_tool_funcs: Mapping[str, Mapping[str, Callable[..., object]]],
) -> dict[str, tuple[MCPToolReference, ...]]:
    """Collect MCP imports from the catalog and fail on name collisions.

    Remote existence is not checked here: that requires ``list_tools`` at
    connection time. Collisions with local/shared callables and reserved
    framework names are static and fail at model load.
    """
    from rasa.mantle.llm.tool_schemas import FRAMEWORK_TOOL_NAMES

    mcp_tool_allowlist_by_skill: dict[str, tuple[MCPToolReference, ...]] = {}
    for skill_id, skill in skill_catalog.skills.items():
        local_tool_funcs = skill_tool_funcs.get(skill_id, {})
        skill_mcp_imports: list[MCPToolReference] = []
        seen_tool_names: set[str] = set()
        for tool_import_reference in sorted(skill.import_tool_names):
            mcp_tool_ref = try_parse_mcp_tool_import(tool_import_reference)
            if mcp_tool_ref is None:
                continue

            if mcp_tool_ref.tool_name in seen_tool_names:
                raise ValueError(
                    f"Skill {skill_id!r} imports more than one MCP tool named "
                    f"{mcp_tool_ref.tool_name!r}."
                )
            seen_tool_names.add(mcp_tool_ref.tool_name)

            if mcp_tool_ref.tool_name in FRAMEWORK_TOOL_NAMES:
                raise ValueError(
                    f"Skill {skill_id!r} MCP import {tool_import_reference!r} "
                    f"reuses reserved framework tool name {mcp_tool_ref.tool_name!r}."
                )
            if mcp_tool_ref.tool_name in local_tool_funcs:
                raise ValueError(
                    f"Skill {skill_id!r} MCP import {tool_import_reference!r} "
                    f"collides with the local/shared tool {mcp_tool_ref.tool_name!r}."
                )
            skill_mcp_imports.append(mcp_tool_ref)

        if skill_mcp_imports:
            mcp_tool_allowlist_by_skill[skill_id] = tuple(skill_mcp_imports)

    return mcp_tool_allowlist_by_skill
